            # cut the word into pieces of exactly width characters
            pieces = []
            for i in range(0, len(word), width):
                pieces.append(word[i:i+width])
            # process each piece as a word by the same rule
            for piece in pieces:
                if current_line and current_length + 1 + len(piece) <= width:
                    current_line.append(piece)
                    current_length = current_length + 1 + len(piece)
